using LinearAlgebra;
using NUnit.Framework;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

// bcgls: block CGLS -- block conjugate gradients on the normal equations A^T A X = A^T B, never
// forming A^T A. The key oracle is BLOCK LEAST-SQUARES OPTIMALITY (normal-equation residual per
// column), not raw residual size -- an overdetermined system has a nonzero residual by construction.
// One [BurstCompile] IJob with a TestType switch, mirroring BlockLSMRTests.double.cs. Every assertion
// runs INSIDE Execute() -- NEVER off a plain job field read after .Run(): IJob.Run() executes on a
// by-value struct copy, so a scalar field write is silently discarded and asserting against its
// default(0) can produce a false green. See OP/DEVLOG.md.
// Unlike blsmr, bcgls tests its convergence on the EXACT maintained S = A^T R (not an estimate), so
// its Solved/converged status is honest in float too -- ConsistentSystem asserts full status for all
// dtypes.
public class doubleBlockCGLSTests
{
    [BurstCompile(CompileSynchronously = true)]
    public struct BlockCGLSTestJob : IJob
    {
        public enum TestType
        {
            NormalEquationsOptimalAndMatchesScalarLsmr,
            ConsistentSystemRecoversExactSolution,
            ZeroRhsConvergesImmediately,
            NeverNaNOnTinyMaxIter,
        }

        public TestType Type;

        public void Execute()
        {
            switch (Type)
            {
                case TestType.NormalEquationsOptimalAndMatchesScalarLsmr: NormalEquationsOptimalAndMatchesScalarLsmr(); break;
                case TestType.ConsistentSystemRecoversExactSolution: ConsistentSystemRecoversExactSolution(); break;
                case TestType.ZeroRhsConvergesImmediately: ZeroRhsConvergesImmediately(); break;
                case TestType.NeverNaNOnTinyMaxIter: NeverNaNOnTinyMaxIter(); break;
            }
        }

        static double Tol() => 1e-6;

        static doubleMxN BuildTallA(ref Arena arena, int m, int n, uint seed)
            => arena.doubleRandomMat(m, n, (double)(-1f), (double)1f, seed);

        static doubleN Row(ref Arena arena, in doubleMxN B, int j, int cols)
        {
            var v = arena.doubleVec(cols);
            for (int c = 0; c < cols; c++) v[c] = B[j, c];
            return v;
        }

        // A^T (A X[j,:] - B[j,:]) for row j -- the normal-equations residual whose smallness IS the
        // least-squares optimality oracle (NOT ||A X - B||, nonzero by construction for overdetermined).
        static double NormalEqResidualNorm(ref Arena arena, in doubleMxN A, in doubleMxN X, in doubleMxN B, int j, int m, int n)
        {
            var xj = Row(ref arena, in X, j, n);
            var r = arena.doubleVec(m);
            Blas.dot(in A, in xj, ref r);
            for (int c = 0; c < m; c++) r[c] -= B[j, c];

            var atr = arena.doubleVec(n);
            Blas.dot(in r, in A, ref atr);
            return math.sqrt(Blas.dot(atr, atr));
        }

        // KEY oracle: per-column normal-equations optimality for a genuine overdetermined system, AND
        // per-column agreement with the scalar lsmr solve of the same column (same LS solution).
        void NormalEquationsOptimalAndMatchesScalarLsmr()
        {
            var arena = new Arena(Allocator.Persistent);

            int m = 24, n = 8, s = 3;
            var A = BuildTallA(ref arena, m, n, 91001u);
            var B = arena.doubleRandomMat(s, m, (double)(-1f), (double)1f, 91002u);

            var X = arena.doubleMat(s, n);
            var info = Krylov.bcgls(in A, in B, ref X, 20 * n, Consts.doubleSqrtEps);

            Assert.IsTrue(info.Solved);
            Assert.AreEqual(s, info.converged);
            Assert.AreEqual(s, info.rhs);

            for (int j = 0; j < s; j++)
            {
                double atrNorm = NormalEqResidualNorm(ref arena, in A, in X, in B, j, m, n);
                Assert.IsTrue((double)atrNorm <= 1e-3);

                var bj = Row(ref arena, in B, j, m);
                var xj = arena.doubleVec(n);
                Assert.IsTrue(Krylov.lsmr(in A, in bj, ref xj, 20 * n, Consts.doubleSqrtEps));

                for (int c = 0; c < n; c++)
                    Assert.IsTrue(math.abs((double)X[j, c] - (double)xj[c]) <= Tol() * (1.0 + math.abs((double)xj[c])));
            }

            arena.Dispose();
        }

        // A CONSISTENT (zero-residual) tall system B = A * Xk must recover Xk exactly. bcgls tests on
        // the exact A^T R, so full-convergence status is honest for every dtype (asserted below).
        void ConsistentSystemRecoversExactSolution()
        {
            var arena = new Arena(Allocator.Persistent);

            int m = 20, n = 6, s = 3;
            var A = BuildTallA(ref arena, m, n, 92001u);
            var Xk = arena.doubleRandomMat(s, n, (double)(-1f), (double)1f, 92002u);

            var B = arena.doubleMat(s, m);
            for (int j = 0; j < s; j++)
            {
                var xkj = Row(ref arena, in Xk, j, n);
                var bj = arena.doubleVec(m);
                Blas.dot(in A, in xkj, ref bj);
                for (int c = 0; c < m; c++) B[j, c] = bj[c];
            }

            var X = arena.doubleMat(s, n);
            var info = Krylov.bcgls(in A, in B, ref X, 20 * n, Consts.doubleSqrtEps);

            Assert.IsTrue(info.Solved);
            Assert.AreEqual(s, info.converged);

            for (int j = 0; j < s; j++)
                for (int c = 0; c < n; c++)
                    Assert.IsTrue(math.abs((double)X[j, c] - (double)Xk[j, c]) <= Tol() * (1.0 + math.abs((double)Xk[j, c])));

            arena.Dispose();
        }

        // B = 0 must converge immediately (X = 0, zero iterations).
        void ZeroRhsConvergesImmediately()
        {
            var arena = new Arena(Allocator.Persistent);

            int m = 16, n = 5, s = 3;
            var A = BuildTallA(ref arena, m, n, 93001u);
            var B = arena.doubleMat(s, m);   // zeroed by allocation

            var X = arena.doubleMat(s, n);
            var info = Krylov.bcgls(in A, in B, ref X, 20 * n, Consts.doubleSqrtEps);

            Assert.IsTrue(info.Solved);
            Assert.AreEqual(0, info.iterations);
            for (int j = 0; j < s; j++)
                for (int c = 0; c < n; c++)
                    Assert.AreEqual(0.0, (double)X[j, c]);

            arena.Dispose();
        }

        // A tiny maxIter must never NaN/Inf X, regardless of solved status.
        void NeverNaNOnTinyMaxIter()
        {
            var arena = new Arena(Allocator.Persistent);

            int m = 30, n = 10, s = 4;
            var A = BuildTallA(ref arena, m, n, 94001u);
            var B = arena.doubleRandomMat(s, m, (double)(-1f), (double)1f, 94002u);

            var X = arena.doubleMat(s, n);
            Krylov.bcgls(in A, in B, ref X, 1, Consts.doubleSqrtEps);

            for (int j = 0; j < s; j++)
                for (int c = 0; c < n; c++)
                    Assert.IsFalse(double.IsNaN((double)X[j, c]) || double.IsInfinity((double)X[j, c]));

            arena.Dispose();
        }
    }

    [Test]
    public void NormalEquationsOptimalAndMatchesScalarLsmr()
        => new BlockCGLSTestJob { Type = BlockCGLSTestJob.TestType.NormalEquationsOptimalAndMatchesScalarLsmr }.Run();

    [Test]
    public void ConsistentSystemRecoversExactSolution()
        => new BlockCGLSTestJob { Type = BlockCGLSTestJob.TestType.ConsistentSystemRecoversExactSolution }.Run();

    [Test]
    public void ZeroRhsConvergesImmediately()
        => new BlockCGLSTestJob { Type = BlockCGLSTestJob.TestType.ZeroRhsConvergesImmediately }.Run();

    [Test]
    public void NeverNaNOnTinyMaxIter()
        => new BlockCGLSTestJob { Type = BlockCGLSTestJob.TestType.NeverNaNOnTinyMaxIter }.Run();
}
